"""The test_story_run_s6 tests were split (TD-11c): the parts hold the checks and story_run_s6_common the shared helpers.
This module re-exports the names other tests import under the old name. It holds no check of its own: the canon
runs each part as its own process. `python -B test_story_run_s6.py --all` runs the parts one after the other.
"""
# split-shim: generated by tools/test_split.py
import subprocess
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
from story_run_s6_common import (  # noqa: E402,F401
    ACCEPTED_S6,
    AWAITS,
    REPLAY_A,
    REPLAY_B,
    Staleness,
    WHY_RUN,
    d1_blocks,
    manual_rig,
    pin_project,
    reprobe_rig,
    row,
    stale_probe,
    t292_config,
    unpin_project,
)

# the re-export is the point of this module: naming it in __all__ keeps it
__all__ = ["ACCEPTED_S6", "AWAITS", "REPLAY_A", "REPLAY_B", "Staleness", "WHY_RUN", "d1_blocks", "manual_rig", "pin_project", "reprobe_rig", "row", "stale_probe", "t292_config", "unpin_project"]

PARTS = ("test_story_run_s6_d1", "test_story_run_s6_manual", "test_story_run_s6_t292", "test_story_run_s6_c16b", "test_story_run_s6_hf2_11b")


def main() -> int:
    if "--all" not in sys.argv[1:]:
        print("test_story_run_s6.py: no checks of its own; they are in " + ", ".join(p + ".py" for p in PARTS))
        return 0
    here = Path(__file__).resolve().parent
    code = 0
    for part in PARTS:
        code = subprocess.run([sys.executable, "-B", str(here / (part + ".py"))]).returncode or code
    return code


if __name__ == "__main__":
    sys.exit(main())
